      "path": ".dsh-plugin/shared/run-ledger.mjs",
      "content": "/**\n * Pure run-ledger logic shared by the Host and the Desktop panel: actual cost\n * from reported token usage, daily/monthly spending, budget decisions, and\n * gentle routing adjustments from user ratings and reviews.\n */\n\nimport { reasoningExecutionFields, unsupportedCliReasoning } from './reasoning-execution.mjs'\nimport { packageSelectionFields } from './package-assignments.mjs'\n\nexport const MAX_STORED_ANSWER = 4_000\nexport const MAX_STORED_TASK = 20_000\n/** Ratings move a route's quality by at most this much (quality is 0–1). */\nexport const MAX_QUALITY_BIAS = 0.04\n\nconst finite = value => typeof value === 'number' && Number.isFinite(value)\nconst nonEmptyText = value => (typeof value === 'string' && value.length > 0 ? value : null)\nconst routeKey = (provider, model) => `${String(provider ?? '')}\\u0000${String(model ?? '')}`\n\nfunction modelIdentity(value) {\n  if (typeof value === 'string' && value.trim()) return value.trim()\n  if (value && typeof value === 'object' && !Array.isArray(value)\n    && typeof value.providerId === 'string' && value.providerId\n    && typeof value.modelId === 'string' && value.modelId) return `${value.providerId}/${value.modelId}`\n  return null\n}\n\n// A stop marker belongs to one attempt, not to earlier requests in a cascade.\n// Contradictory positive/invalid counters remain potentially paid evidence.\nfunction clearlyNotStarted(attempt) {\n  if (!attempt || typeof attempt !== 'object' || (attempt.notStarted !== true && attempt.blocked !== true)) return false\n  if (Object.hasOwn(attempt, 'reportedCostUsd') && attempt.reportedCostUsd !== undefined\n    && attempt.reportedCostUsd !== null && attempt.reportedCostUsd !== 0) return false\n  return !['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheWriteTokens'].some(key => {\n    const value = attempt.usage?.[key]\n    return value !== undefined && value !== null && value !== 0\n  })\n}\n\n/** True when some quality attempt ran, or execution cannot safely be ruled out. */\nexport function hasStartedQualityAttempts(result) {\n  if (!result || !Object.hasOwn(result, 'qualityAttempts')) return false\n  const attempts = result.qualityAttempts\n  if (!Array.isArray(attempts) || attempts.length < 1 || attempts.length > 2) return true\n  return attempts.some(attempt => !clearlyNotStarted(attempt))\n}\n\n/** USD cost of one package. Prefers a CLI-reported cost, else usage × configured price. */\nexport function actualCost(result, pricing) {\n  if (result && Object.hasOwn(result, 'qualityAttempts')) {\n    const attempts = result.qualityAttempts\n    if (!Array.isArray(attempts) || attempts.length < 1 || attempts.length > 2\n      || attempts.some(item => !item || typeof item !== 'object' || Object.hasOwn(item, 'qualityAttempts')\n        || item.channel === 'official-cli' || item.billing === 'subscription')) {\n      return { costUsd: null, costSource: 'quality-attempts-invalid' }\n    }\n    const costs = attempts.map(item => clearlyNotStarted(item)\n      ? { costUsd: 0, costSource: 'not-run' }\n      : actualCost(item, item.pricingSnapshot ?? null))\n    if (costs.some(item => item.costUsd === null)) {\n      const knownCostUsd = costs.filter(item => item.costUsd !== null).reduce((sum, item) => sum + item.costUsd, 0)\n      return finite(knownCostUsd) ? { costUsd: null, costSource: 'quality-attempts-incomplete', knownCostUsd,\n        unknownAttemptCount: costs.filter(item => item.costUsd === null).length }\n        : { costUsd: null, costSource: 'cost-invalid' }\n    }\n    const total = costs.reduce((sum, item) => sum + item.costUsd, 0)\n    return finite(total) && total >= 0 ? { costUsd: total, costSource: 'quality-attempts' }\n      : { costUsd: null, costSource: 'cost-invalid' }\n  }\n  if (result && Object.hasOwn(result, 'reportedCostUsd') && finite(result.reportedCostUsd) && result.reportedCostUsd >= 0) {\n    return { costUsd: result.reportedCostUsd, costSource: 'cli-reported' }\n  }\n  const usage = result && Object.hasOwn(result, 'usage') ? result.usage : null\n  if (usage && result.usageIncomplete === true) return { costUsd: null, costSource: 'usage-incomplete' }\n  if (usage && result.channel === 'official-cli') {\n    const actualModel = modelIdentity(result.actualModel) ?? modelIdentity(result.reportedModel)\n    if (!actualModel) return { costUsd: null, costSource: 'model-unknown' }\n    const pricedModel = pricing?.model ?? result.model\n    const provider = pricing?.provider ?? result.provider\n    const matches = [pricedModel, pricing?.cliModel, provider && pricedModel ? `${provider}/${pricedModel}` : null]\n      .some(value => typeof value === 'string' && value === actualModel)\n    if (!matches) return { costUsd: null, costSource: 'model-price-unverified' }\n  }\n  if (!usage || !pricing || !Object.hasOwn(pricing, 'input') || !Object.hasOwn(pricing, 'output')\n    || pricing.input === undefined || pricing.input === null || pricing.output === undefined || pricing.output === null) {\n    return { costUsd: null, costSource: usage ? 'price-missing' : 'usage-missing' }\n  }\n  const nonnegative = value => finite(value) && value >= 0\n  if (typeof pricing !== 'object' || Array.isArray(pricing)\n    || !nonnegative(pricing.input) || !nonnegative(pricing.output)\n    || ['cacheRead', 'cacheWrite'].some(key => Object.hasOwn(pricing, key) && pricing[key] !== undefined && !nonnegative(pricing[key]))) {\n    return { costUsd: null, costSource: 'price-invalid' }\n  }\n  if (typeof usage !== 'object' || Array.isArray(usage)) return { costUsd: null, costSource: 'usage-invalid' }\n  if (!Object.hasOwn(usage, 'inputTokens') || !Object.hasOwn(usage, 'outputTokens')\n    || usage.inputTokens === undefined || usage.inputTokens === null || usage.outputTokens === undefined || usage.outputTokens === null) {\n    return { costUsd: null, costSource: 'usage-missing' }\n  }\n  if (['inputTokens', 'outputTokens'].some(key => !nonnegative(usage[key]))\n    || ['cacheReadTokens', 'cacheWriteTokens'].some(key => Object.hasOwn(usage, key) && usage[key] !== undefined && !nonnegative(usage[key]))) {\n    return { costUsd: null, costSource: 'usage-invalid' }\n  }\n  const input = usage.inputTokens\n  const output = usage.outputTokens\n  const cacheRead = Object.hasOwn(usage, 'cacheReadTokens') ? usage.cacheReadTokens ?? 0 : 0\n  const cacheWrite = Object.hasOwn(usage, 'cacheWriteTokens') ? usage.cacheWriteTokens ?? 0 : 0\n  const cacheReadPrice = Object.hasOwn(pricing, 'cacheRead') ? pricing.cacheRead ?? pricing.input : pricing.input\n  const cacheWritePrice = Object.hasOwn(pricing, 'cacheWrite') ? pricing.cacheWrite ?? pricing.input : pricing.input\n  // Divide each usage counter before multiplication to avoid intermediate\n  // overflow for a finite USD result; an actually unrepresentable cost is unknown.\n  const costUsd = input / 1_000_000 * pricing.input\n    + cacheRead / 1_000_000 * cacheReadPrice\n    + cacheWrite / 1_000_000 * cacheWritePrice\n    + output / 1_000_000 * pricing.output\n  if (!nonnegative(costUsd)) return { costUsd: null, costSource: 'cost-invalid' }\n  return { costUsd, costSource: 'usage' }\n}\n\n/**\n * Who pays for a package. `api`: an API key or the model-catalog API, counted\n * against budgets. `subscription`: an official CLI on its own account login with\n * no API key injected; its CLI-reported or usage × price figure is only an\n * API-equivalent reference and is not counted against budgets.\n * `loginBilling` comes from the health check ('api-key' when the CLI's own\n * login is an API key). `apiKeyPresent` is for runners that do not report\n * `credentialSource` (the signed team runner inherits vendor key variables).\n */\nexport function billingOf(result, { loginBilling = null, apiKeyPresent = false } = {}) {\n  if (!result || result.blocked) return null\n  // The subscription-first executor states the channel it billed explicitly.\n  if (result.billing === 'api' || result.billing === 'subscription') return result.billing\n  if (result.channel !== 'official-cli') return 'api'\n  if (result.credentialSource === 'configured-api-key' || result.credentialSource === 'process-environment') return 'api'\n  if (!result.credentialSource && apiKeyPresent) return 'api'\n  return loginBilling === 'api-key' ? 'api' : 'subscription'\n}\n\n/** Cost fields for storage: subscription runs keep the figure as `referenceCostUsd` only. */\nexport function billedCost(result, pricing, billing) {\n  const cost = actualCost(result, pricing)\n  if (billing !== 'subscription') return { ...cost, billing: billing ?? 'api', referenceCostUsd: null }\n  return { costUsd: null, costSource: cost.costSource, billing, referenceCostUsd: cost.costUsd }\n}\n\nconst pad = value => String(value).padStart(2, '0')\n/** Local calendar keys (the Host's time zone, which is the user's machine). */\nexport const dayKey = at => { const date = new Date(at); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` }\nexport const monthKey = at => { const date = new Date(at); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}` }\n\n/** Detailed history can be evicted without losing the current budget totals. */\nexport const MAX_SPENDING_DAYS = 90\nexport const MAX_SPENDING_MONTHS = 24\nconst emptyPeriodSpending = () => ({ costUsd: 0, unknown: 0, subscriptionUsd: 0, subscriptionRuns: 0 })\n\nfunction periodSpending(value) {\n  const amount = field => finite(value?.[field]) && value[field] >= 0 ? value[field] : 0\n  return { costUsd: amount('costUsd'), unknown: Math.floor(amount('unknown')),\n    subscriptionUsd: amount('subscriptionUsd'), subscriptionRuns: Math.floor(amount('subscriptionRuns')) }\n}\n\n/** Bounded calendar aggregates contain amounts and counts, never tasks or answers. */\nexport function sanitizeArchivedSpending(value) {\n  const periods = (entries, pattern, limit) => Object.fromEntries(Object.entries(entries && typeof entries === 'object' && !Array.isArray(entries) ? entries : {})\n    .filter(([key, entry]) => pattern.test(key) && entry && typeof entry === 'object' && !Array.isArray(entry))\n    .sort(([left], [right]) => left.localeCompare(right)).slice(-limit)\n    .map(([key, entry]) => [key, periodSpending(entry)]))\n  return {\n    days: periods(value?.days, /^\\d{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12]\\d|3[01])$/, MAX_SPENDING_DAYS),\n    months: periods(value?.months, /^\\d{4}-(?:0[1-9]|1[0-2])$/, MAX_SPENDING_MONTHS),\n  }\n}\n\nfunction addArchivedSpending(target, source) {\n  const archive = sanitizeArchivedSpending(source)\n  for (const period of ['days', 'months']) {\n    for (const [key, amount] of Object.entries(archive[period])) {\n      const total = target[period][key] ??= emptyPeriodSpending()\n      for (const field of Object.keys(amount)) total[field] += amount[field]\n    }\n  }\n}\n\nfunction* spendingEntries(runs) {\n  for (const run of Array.isArray(runs) ? runs : []) {\n    for (const item of [...(Array.isArray(run?.packages) ? run.packages : []), ...(Array.isArray(run?.reviews) ? run.reviews : [])]) {\n      if (!item || typeof item !== 'object') continue\n      const when = item.finishedAt ?? run.createdAt\n      if (!finite(when) || !finite(new Date(when).getTime())) continue\n      const amount = emptyPeriodSpending()\n      if (item.billing === 'subscription') {\n        // A subscription login is reference cost only, never budget spend.\n        if (item.ran !== true) continue\n        amount.subscriptionRuns = 1\n        if (finite(item.referenceCostUsd) && item.referenceCostUsd >= 0) amount.subscriptionUsd = item.referenceCostUsd\n      } else if (finite(item.costUsd) && item.costUsd >= 0) amount.costUsd = item.costUsd\n      else if (item.ran === true) {\n        amount.unknown = 1\n        if (finite(item.knownCostUsd) && item.knownCostUsd >= 0) amount.costUsd = item.knownCostUsd\n      }\n      else continue\n      yield { when, amount }\n    }\n  }\n}\n\n/** Fold only evicted records into the archive; retained records are counted live. */\nexport function archiveSpending(runs, archivedSpending) {\n  const archive = sanitizeArchivedSpending(archivedSpending)\n  for (const run of Array.isArray(runs) ? runs : []) addArchivedSpending(archive, run?.priorAttemptSpending)\n  for (const { when, amount } of spendingEntries(runs)) {\n    for (const [periods, key] of [[archive.days, dayKey(when)], [archive.months, monthKey(when)]]) {\n      const total = periods[key] ??= emptyPeriodSpending()\n      for (const field of Object.keys(amount)) total[field] += amount[field]\n    }\n  }\n  return sanitizeArchivedSpending(archive)\n}\n\n/** Recorded spending, including evicted history, for the local day and month. */\nexport function spending(runs, at = Date.now(), archivedSpending = null) {\n  const today = dayKey(at)\n  const month = monthKey(at)\n  const archive = sanitizeArchivedSpending(archivedSpending)\n  for (const run of Array.isArray(runs) ? runs : []) addArchivedSpending(archive, run?.priorAttemptSpending)\n  const daily = periodSpending(archive.days[today])\n  const monthly = periodSpending(archive.months[month])\n  const total = { today: daily.costUsd, month: monthly.costUsd, unknownToday: daily.unknown, unknownMonth: monthly.unknown,\n    subscriptionToday: daily.subscriptionUsd, subscriptionMonth: monthly.subscriptionUsd,\n    subscriptionRunsToday: daily.subscriptionRuns, subscriptionRunsMonth: monthly.subscriptionRuns }\n  for (const { when, amount } of spendingEntries(runs)) {\n    if (monthKey(when) !== month) continue\n    total.month += amount.costUsd\n    total.unknownMonth += amount.unknown\n    total.subscriptionMonth += amount.subscriptionUsd\n    total.subscriptionRunsMonth += amount.subscriptionRuns\n    if (dayKey(when) === today) {\n      total.today += amount.costUsd\n      total.unknownToday += amount.unknown\n      total.subscriptionToday += amount.subscriptionUsd\n      total.subscriptionRunsToday += amount.subscriptionRuns\n    }\n  }\n  return total\n}\n\n/**\n * Decide whether a run fits the configured limits. A zero limit is off.\n * `estimateUsd` null means prices are missing; only already-exceeded limits block then.\n */\n/** USD amounts in budget messages and the workbench: always four decimals, so limits and spend line up. */\nexport function formatUsd(value) {\n  return typeof value === 'number' && Number.isFinite(value) ? `$${value.toFixed(4)}` : '—'\n}\n\nexport function budgetCheck({ estimateUsd = null, spent = { today: 0, month: 0 }, dailyLimitUsd = 0, monthlyLimitUsd = 0 } = {}) {\n  const limits = []\n  if (finite(dailyLimitUsd) && dailyLimitUsd > 0) limits.push({ period: 'daily', label: '今日', limit: dailyLimitUsd, spent: spent.today ?? 0 })\n  if (finite(monthlyLimitUsd) && monthlyLimitUsd > 0) limits.push({ period: 'monthly', label: '本月', limit: monthlyLimitUsd, spent: spent.month ?? 0 })\n  const estimateKnown = finite(estimateUsd)\n  const remaining = limits.length ? Math.max(0, Math.min(...limits.map(item => item.limit - item.spent))) : null\n  const exceeded = limits.find(item => item.spent >= item.limit || (estimateKnown && item.spent + estimateUsd > item.limit)) ?? null\n  return {\n    limited: limits.length > 0,\n    estimateKnown,\n    estimateUsd: estimateKnown ? estimateUsd : null,\n    remainingUsd: remaining,\n    exceeded: exceeded ? exceeded.period : null,\n    message: exceeded\n      ? `${exceeded.label}预算 ${formatUsd(exceeded.limit)}，已用 ${formatUsd(exceeded.spent)}${estimateKnown ? `，本次预估 ${formatUsd(estimateUsd)}` : ''}，将超出上限。`\n      : limits.length && !estimateKnown ? '部分路线缺少单价，无法预估本次费用；仅在已用金额达到上限时阻止。' : '',\n  }\n}\n\n/**\n * Per-route quality bias from ratings (+1/-1) and reviews (score 1–5).\n * Bayesian-shrunk toward 0 so a single rating barely moves routing.\n */\nexport function routeQualityBiases(runs) {\n  const tally = new Map()\n  for (const run of Array.isArray(runs) ? runs : []) {\n    for (const item of run.packages ?? []) {\n      const key = routeKey(item.provider, item.model)\n      const entry = tally.get(key) ?? { sum: 0, weight: 0, ratings: 0 }\n      if (item.rating === 1 || item.rating === -1) { entry.sum += item.rating; entry.weight += 1; entry.ratings += 1 }\n      if (finite(item.review?.score)) { entry.sum += 0.5 * ((item.review.score - 3) / 2); entry.weight += 0.5 }\n      tally.set(key, entry)\n    }\n  }\n  const biases = {}\n  for (const [key, entry] of tally) {\n    if (entry.weight === 0) continue\n    const bias = MAX_QUALITY_BIAS * entry.sum / (entry.weight + 3)\n    biases[key] = Math.max(-MAX_QUALITY_BIAS, Math.min(MAX_QUALITY_BIAS, Number(bias.toFixed(4))))\n  }\n  return biases\n}\n\n/** Attach biases to exact routes; the planner adds them to estimated quality. */\nexport function applyQualityBiases(routes, biases) {\n  if (!biases || typeof biases !== 'object') return routes\n  return (Array.isArray(routes) ? routes : []).map(route => {\n    const bias = biases[routeKey(route.provider, route.model)]\n    return finite(bias) && bias !== 0 ? { ...route, qualityBias: bias } : route\n  })\n}\n\nfunction storedPackage(planned, result, pricing, finishedAt, billingFor = billingOf) {\n  const plannedEffort = nonEmptyText(planned?.recommendedReasoningEffort) ?? nonEmptyText(planned?.plannedReasoningEffort)\n  const startedAttempts = hasStartedQualityAttempts(result)\n  const qualityAttempts = Array.isArray(result?.qualityAttempts)\n    ? result.qualityAttempts.slice(0, 2).map(attempt => attempt && typeof attempt === 'object' ? attempt : {}) : null\n  const cost = !result || ((result.blocked || result.notStarted) && !startedAttempts)\n    ? { costUsd: null, costSource: 'not-run', billing: null, referenceCostUsd: null }\n    : billedCost(result, pricing, billingFor(result))\n  return {\n    id: planned.id,\n    ...packageSelectionFields(result?.manualAssignment !== undefined ? { ...planned, ...result } : planned),\n    name: planned.name,\n    objective: String(planned.objective ?? '').slice(0, 2_